Q: Getting pyAgrum error: &#39;Object not found: label &#39;x&#39; is unknown A: <pre><code>&quot;&quot;&quot;
Décorateurs pour le logging automatique.

Facilite le logging des entrées/sorties de fonctions et
la mesure des temps d'exécution.
&quot;&quot;&quot;

import logging
import functools
import time
from typing import Callable, TypeVar, Any, Optional

F = TypeVar('F', bound=Callable[..., Any])


def with_logging(
    log_args: bool = True,
    log_result: bool = False,
    level: int = logging.INFO
) -&gt; Callable[[F], F]:
    &quot;&quot;&quot;
    Décorateur pour logger automatiquement les appels de fonction.

    Args:
        log_args: Logger les arguments d'entrée
        log_result: Logger le résultat de sortie
        level: Niveau de log (INFO par défaut)

    Returns:
        Décorateur qui wrappe la fonction

    Example:
        &gt;&gt;&gt; @with_logging(log_args=True, log_result=True)
        ... def process_data(table_name: str, limit: int = 100):
        ...     return f&quot;Processed {limit} rows from {table_name}&quot;
    &quot;&quot;&quot;

    def decorator(func: F) -&gt; F:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -&gt; Any:
            # Récupérer le logger
            if args and hasattr(args[0], 'logger'):
                logger = args[0].logger
            else:
                logger = logging.getLogger(func.__module__)

            # Logger les arguments
            if log_args:
                args_repr = _format_args(args, kwargs)
                logger.log(level, f&quot;{func.__name__}({args_repr})&quot;)
            else:
                logger.log(level, f&quot;{func.__name__}() called&quot;)

            # Exécuter la fonction
            result = func(*args, **kwargs)

            # Logger le résultat si demandé
            if log_result:
                result_repr = _format_result(result)
                logger.log(level, f&quot;{func.__name__}() -&gt; {result_repr}&quot;)

            return result

        return wrapper  # type: ignore

    return decorator


def log_execution_time(
    operation_name: Optional[str] = None,
    threshold_seconds: float = 0.0
) -&gt; Callable[[F], F]:
    &quot;&quot;&quot;
    Décorateur pour mesurer et logger le temps d'exécution.

    Args:
        operation_name: Nom de l'opération (utilise func.__name__ si None)
        threshold_seconds: Ne logger que si durée &gt; seuil (0 = toujours logger)

    Returns:
        Décorateur qui wrappe la fonction

    Example:
        &gt;&gt;&gt; @log_execution_time(&quot;data processing&quot;, threshold_seconds=1.0)
        ... def process_large_dataset(table_name: str):
        ...     # Traitement long
        ...     time.sleep(2)
        ...     return &quot;Done&quot;
    &quot;&quot;&quot;

    def decorator(func: F) -&gt; F:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -&gt; Any:
            # Récupérer le logger
            if args and hasattr(args[0], 'logger'):
                logger = args[0].logger
            else:
                logger = logging.getLogger(func.__module__)

            # Nom de l'opération
            op_name = operation_name or func.__name__

            # Mesurer le temps
            start_time = time.time()
            try:
                result = func(*args, **kwargs)
                return result
            finally:
                duration = time.time() - start_time

                # Logger si au-dessus du seuil
                if duration &gt;= threshold_seconds:
                    logger.info(f&quot;{op_name} completed in {duration:.2f}s&quot;)

        return wrapper  # type: ignore

    return decorator


def _format_args(args: tuple, kwargs: dict) -&gt; str:
    &quot;&quot;&quot;
    Formate les arguments pour le logging.

    Args:
        args: Arguments positionnels
        kwargs: Arguments nommés

    Returns:
        String formaté des arguments
    &quot;&quot;&quot;
    # Skip self/cls
    args_to_format = args[1:] if args and _is_method_call(args) else args

    # Formatter les args positionnels
    args_repr = [repr(arg) for arg in args_to_format]

    # Formatter les kwargs
    kwargs_repr = [f&quot;{k}={v!r}&quot; for k, v in kwargs.items()]

    return &quot;, &quot;.join(args_repr + kwargs_repr)


def _format_result(result: Any) -&gt; str:
    &quot;&quot;&quot;
    Formate le résultat pour le logging.

    Args:
        result: Résultat de la fonction

    Returns:
        String formaté du résultat
    &quot;&quot;&quot;
    # Cas spéciaux
    if hasattr(result, 'success'):
        # ProcessingResult ou ServiceResult
        return f&quot;{'Success' if result.success else 'Failed'}&quot;

    # Résultat générique
    result_str = repr(result)
    if len(result_str) &gt; 100:
        result_str = result_str[:97] + &quot;...&quot;

    return result_str


def _is_method_call(args: tuple) -&gt; bool:
    &quot;&quot;&quot;
    Détermine si c'est un appel de méthode (avec self/cls).

    Args:
        args: Arguments positionnels

    Returns:
        True si c'est un appel de méthode
    &quot;&quot;&quot;
    return bool(args and hasattr(args[0], '__class__'))


# Type hint pour compatibilité
from typing import Optional
</code></pre>

Q: How to handle RpcException in NestJS A: <p>I ran into the same issue and went for a different approach than the one shown in <a href="https://stackoverflow.com/questions/72152120/how-to-handle-rpcexception-in-nestjs/75335979#75335979">this answer.</a> (I was also using NATS, not gRPC)</p>
<p>I had a main API gateway (<code>client-gateway</code>) and a specific microservice for authentication (<code>auth-ms</code>), and I wanted any error thrown in the microservice to &quot;bubble up&quot; to the global exception filter on the gateway and return an appropiate response to the client.</p>
<p>IMO, each microservice should handle its own errors and adapt to a specific contract/interface on how should any <code>RpcException</code> arrive to the api gateway (this mainly due to the fact that different microservices work with different databases, caches, third party applications. Handle each one of them in only one place - api gateway filter- felt like mixing logic that could remain separated).</p>
<p>Therefore <code>auth-ms</code> had it its own <code>RpcGlobalExceptionFilter</code> that handled custom exceptions that extended <code>RpcException</code></p>
<p><strong>Microservice (remember to use <code>inheritAppConfig</code>  if your ms is hybrid and you registered it with <code>APP_FILTER</code>)</strong></p>
<pre class="lang-ts prettyprint-override"><code>// unauthorized-rpc.exception.ts

export class UnauthorizedRpcException extends RpcException {
  constructor(message: string) {
    super({
      statusCode: HttpStatus.UNAUTHORIZED,
      message,
      type: UnauthorizedException.name,
    //... pretty much whatever you need, even make dynamic with the constructor
    });
  }
}

// auth.controller.ts

  @MessagePattern('auth.login.user')
  async login(
    @Payload() loginUserDto: LoginUserDTO,
  ): Promise&lt;{ accessToken: string; refreshToken: string }&gt; {
    const { accessToken, refreshToken } =
      await this.authService.loginUser(loginUserDto);
    return { accessToken, refreshToken };
  }

// auth.service.ts

  async loginUser(loginUserDto: LoginUserDTO): Promise&lt;UserTokens&gt; {
    const user = await this.authUserService.findOneBySlug(loginUserDto);

    if (!user || !(await checkHash(loginUserDto.password, user.hash))) {
    // this is the relevant part
      throw new UnauthorizedRpcException(
        ErrorMessages.INVALID_USER_CREDENTIALS,
      );
    }

    // some logic to sign and return user tokens...

    return { accessToken, refreshToken };
  }


// rpc-global-exception.filter.ts

// THIS IS THE SHARED CONTRACT, you can make it as flexible or strict as you need
interface InternalRpcErrorResponse {
  origin: string;
  code: string | number; // you can use gRPC Status
  error?: { statusCode?: string | number; message?: string; type?: string }; // I needed something like this in the api gateway filter to map them correctly
  message?: string;
}

@Catch() // catch all since exception layer catches database errors, etc.
export class RpcGlobalExceptionFilter extends BaseRpcExceptionFilter&lt;any&gt; {
  constructor() {
    super();
  }

  catch(exception: unknown, host: ArgumentsHost): Observable&lt;any&gt; {
    // set up your logger for better monitoring

    let mappedException: InternalRpcErrorResponse = {
      origin: 'auth-ms',
    };

    // * All custom exceptions extended from RpcException handled here
    if (exception instanceof RpcException) {
      mappedException = { ...mappedException, ...(exception as object) };
    }

    // * Database connection error
    if (exception instanceof AggregateError) {
      // send what you need...
    }
    // * TypeORM errors
    if (exception instanceof TypeORMError) {
      // same thing...
    }

    return super.catch(new RpcException(mappedException), host);
  }
}
</code></pre>
<p><strong>Gateway</strong></p>
<pre class="lang-ts prettyprint-override"><code>// auth.controller.ts

 @Post('login')
  async login(
    @Body() loginUserDto: LoginUserDTO,
    @Res({ passthrough: true }) response: ExpressResponse,
  ): Promise&lt;{ accessToken: string }&gt; {
    // no pipe to catch error as it is already handled by the global filter in the gateway
    const { accessToken, refreshToken } = await firstValueFrom&lt;{
      accessToken: string;
      refreshToken: string;
    }&gt;(this.client.send('auth.login.user', loginUserDto));

    // ... set refresh token in cookie

    return { accessToken };
  }

// global-exception.filter.ts

interface ErrorResponse {
  message: string;
  error: string;
  statusCode: number | string;
  details?: any;
}

interface InternalRpcErrorResponse { 
// same definition, you could set up a shared lib if you have a monorepo structure or nest workspace
}

@Catch() // catch all, again
export class GlobalExceptionsFilter extends BaseExceptionFilter&lt;any&gt; {
  constructor() {
    super();
  }

  catch(exception: unknown, host: ArgumentsHost) {
    const response = host.switchToHttp().getResponse&lt;Response&gt;();
    // set up your logger for better monitoring

    // generic error so you avoid sending crude error to the client
    const errorResponse: ErrorResponse = {
      message: 'Something went wrong',
      error: 'Internal Server Error',
      statusCode: HttpStatus.INTERNAL_SERVER_ERROR,
      details: 'Check logs',
    };

    // * Errors sent from microservices fall here
    // NestJS does not persist exception instance between apps/ms, it catches any exception sent by microservices as a generic objects
    if (
      exception instanceof Object &amp;&amp;
      'origin' in exception &amp;&amp;
      'code' in exception
    ) {
      // you can do your own thing, this is just how I managed it
      const rpcException = new RpcException(exception);
      const exceptionResponse =
        rpcException.getError() as InternalRpcErrorResponse;

      errorResponse.message =
        exceptionResponse.message ?? errorResponse.message;
      errorResponse.error = exceptionResponse.error?.type ?? 'RpcException'; // mapping should be done here, UnauthorizedException.name
      errorResponse.statusCode = exceptionResponse.error?.statusCode ?? 500;
      errorResponse.details = { code: exception.code };
    }


    // you can organize this as you deem fit, I liked my http errors in api gateway be catched first
    if (exception instanceof HttpException) {
      super.catch(exception, host);
      return;
    } else {
      // * TCP/NATS error
      if (exception instanceof NatsError) {
        errorResponse.details = exception.message;
      }
      // * Auth errors handled here since auth uses private/public key, so no need to hit auth service
      if (
        exception instanceof TokenExpiredError ||
        exception instanceof JsonWebTokenError
      ) {
        // ...
      }

      response.status(Number(errorResponse.statusCode)).json(errorResponse);
    }
  }
}
</code></pre>
<p>Hope it broads your horizon of options when designing your error handling</p>
